style.css:
@-moz-document domain("roblox.com") {
body, html {
        background: url("https://www.pinterest.com/pin/7459155629199396/") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Make main containers transparent or dark */
    .container-main, 
    .content,
    .section,
    .rbx-navbar,
    .game-details-page,
    .page-content,
    #main-content,
    .content-wrapper,
    .page-container {
        background-color: rgba(0, 0, 0, 0.6) !important;
        color: white !important;
    }
}
